import{_ as s,o as n,c as e,aj as i}from"./chunks/framework.BdtAaXf2.js";const t="/assets/image-20251029185603599.B5R1mBlA.png",l="/assets/image-20251029185611968.Z3WpPMV_.png",r="/assets/image-20251029185624498.BfhMW7YJ.png",p="/assets/image-20251029185710386.DWk0rdu_.png",o="/assets/image-20251029185728781.Cr4j328J.png",c="/assets/image-20251029190449845.CAoViloE.png",E=JSON.parse('{"title":"Trae AI 编辑器6大使用规则","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/Trae AI 编辑器6大使用规则/Trae AI 编辑器6大使用规则.md","filePath":"鸿蒙开发技巧/Trae AI 编辑器6大使用规则/Trae AI 编辑器6大使用规则.md","lastUpdated":1762865236000,"__rawMarkdown":"# Trae AI 编辑器6大使用规则\\n\\n> 海外版本  claude 4.0  版本\\n\\n## 一 规则\\n\\n你可以给trae 制定每一次 编码时要遵守的规则  (有概率遗忘)\\n\\n1. user_rules 用户规则 ， 只要是使用trae，就会沿用这个规则\\n2. **project_rules** 项目规则，不同的项目有不同项目的规则\\n\\n![](assets/image-20251029185603599.png)\\n\\n## 二 自然语言描述需求\\n\\n> 越具体越好\\n\\n1. 对话前，让它先通读一下你的规则文件 ，然后再开始生成代码 \\n\\n![](assets/image-20251029185611968.png)\\n\\n2. 自然语言\\n\\n ```JSON\\n      我想要生成一个 pc端的web的打字游戏网站\\n      \\n      - 使用html+css+js来实现\\n      \\n      - 功能包括有，输入玩家姓名、记录分数\\n      \\n      - 游戏界面要求炫酷，可玩性高\\n ```\\n3. 合理利用范围工具 \\n\\n![](assets/image-20251029185624498.png)\\n\\n## 三 一定要使用git管理代码\\n\\n> 预防本次对话生成代码不合理，做好回退\\n\\n## 四 使用好 mcp 工具 \\n\\nmcp 等于 给ai编辑器 增强各个方面的能力  context7 -> 让大模型 优先使用最新的代码技术！！！ \\n\\n![](assets/image-20251029185710386.png)\\n\\n## 五 把准确的文档放到工程中，让ai参考，再去编码\\n\\n![](assets/image-20251029185728781.png)\\n\\n## 六 大功能完成了就新开一个对话，然后重复 读规则的步骤\\n\\n\\n\\n![](assets/image-20251029190449845.png)"}'),h={name:"鸿蒙开发技巧/Trae AI 编辑器6大使用规则/Trae AI 编辑器6大使用规则.md"};function m(d,a,g,_,u,b){return n(),e("div",null,[...a[0]||(a[0]=[i("",23)])])}const q=s(h,[["render",m]]);export{E as __pageData,q as default};
